package viewcmds_test

import (
	"testing"

	"stuntgres/internal/engine"
	"stuntgres/internal/engine/core"
	"stuntgres/internal/engine/enginetest"
	"stuntgres/internal/engine/ids"
	"stuntgres/internal/engine/view"
)

// TestViewHostSeam pins the view.Host and view.StageHost seam: a stage-less
// ddlHost names the session as the temporary owner, and ReownDisplacedTypes
// changes nothing on a stage that renamed no names, but reowns after an
// autogenerated array is displaced.
func TestViewHostSeam(t *testing.T) {
	e := engine.New()
	op, done := enginetest.RoleOperation(t, e, "postgres")
	defer done()
	enginetest.RoleExecute(t, e, op, "CREATE TABLE displaced(id INTEGER)")
	e.Mu.Lock()
	defer e.Mu.Unlock()
	auth, err := e.AuthorizationLocked(op)
	if err != nil {
		t.Fatal(err)
	}
	var h view.Host = engine.ViewHost{TableHost: engine.TableHost{DDLHost: core.DDLHost{E: e, Op: op}}}
	if got := h.TemporaryOwner(auth); got != op.Session.SessionToken || got == (ids.SessionToken{}) {
		t.Fatalf("TemporaryOwner = %v, want the session token %v", got, op.Session.SessionToken)
	}
	public, ok := auth.Catalog.LookupName(ids.NameKey{ClassID: ids.NamespaceClassID, Name: "public"})
	if !ok {
		t.Fatal("public namespace is missing")
	}

	clean := e.BeginCatalogStage(auth.Catalog)
	defer e.DiscardCatalogStage(clean)
	var sh view.StageHost = engine.ViewHost{TableHost: engine.TableHost{DDLHost: core.DDLHost{E: e, Op: op, CatalogStage: clean}}}
	if err := sh.ReownDisplacedTypes(); err != nil {
		t.Fatal(err)
	}
	if clean.DescriptorCount() != 0 || clean.OldNameCount() != 0 {
		t.Fatalf("ReownDisplacedTypes changed a clean stage: %d descriptors, %d old names", clean.DescriptorCount(), clean.OldNameCount())
	}

	displaced := e.BeginCatalogStage(auth.Catalog)
	defer e.DiscardCatalogStage(displaced)
	sh = engine.ViewHost{TableHost: engine.TableHost{DDLHost: core.DDLHost{E: e, Op: op, CatalogStage: displaced}}}
	available, err := sh.DisplaceAssociatedArray(public, "_displaced")
	if err != nil || !available {
		t.Fatalf("DisplaceAssociatedArray = %v, %v; want the array displaced", available, err)
	}
	if displaced.OldNameCount() == 0 {
		t.Fatal("displacing the array renamed no names")
	}
	if err := sh.ReownDisplacedTypes(); err != nil {
		t.Fatal(err)
	}
}
